// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostQuote.ChunkedWork;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.junit.jupiter.api.Test;

/** Root construction and output replay retain independent demand and scaling units. */
class LmdbNativeIndependentChunkedWorkTest {

	@Test
	void shortRootEarlyReturnDoesNotDrainIndependentReplay() {
		LmdbNativeCostQuote quote = quote(rootAndReplay());
		LmdbNativeCostVector first = quote.forSlice(1D);
		assertThat(first.expected(Feature.BATCH_ROW)).isEqualTo(7D);
		assertThat(first.expected(Feature.GENERATED_ROW)).isEqualTo(5D);
		assertThat(first.high(Feature.GENERATED_ROW)).isEqualTo(100D);
		assertThat(first.expected(Feature.OUTPUT_MATERIALIZATION)).isEqualTo(1D);
		assertThat(quote.forSlice(5D).expected(Feature.GENERATED_ROW)).isEqualTo(5D);
		assertThat(quote.forSlice(6D).expected(Feature.GENERATED_ROW)).isEqualTo(10D);
	}

	@Test
	void zeroFullAndUnknownDemandPreserveBothPhases() {
		LmdbNativeCostQuote quote = quote(rootAndReplay());
		assertThat(quote.forSlice(0D).expected(Feature.BATCH_ROW)).isZero();
		assertThat(quote.forSlice(0D).expected(Feature.GENERATED_ROW)).isZero();
		assertThat(quote.forSlice(100D).expected(Feature.BATCH_ROW)).isEqualTo(7D);
		assertThat(quote.forSlice(100D).expected(Feature.GENERATED_ROW)).isEqualTo(100D);
		assertThat(quote.withOutputRows(Double.NaN).forSlice(1D).expected(Feature.GENERATED_ROW)).isEqualTo(100D);
	}

	@Test
	void scaleChangesRootWaveWithoutChangingIndependentReplayWidth() {
		ChunkedWork work = rootAndReplay().scaled(0.5D, 64)
				.withChunkSetup(LmdbNativeCostVector.point(Feature.OPEN, 3D), 32);
		LmdbNativeCostVector first = work.forSlice(1D, 100D);
		assertThat(first.expected(Feature.BATCH_ROW)).isEqualTo(3.5D);
		assertThat(first.expected(Feature.GENERATED_ROW)).isEqualTo(2.5D);
		assertThat(first.expected(Feature.OPEN)).isEqualTo(3D);
		assertThat(work.vector().expected(Feature.GENERATED_ROW)).isEqualTo(50D);
	}

	@Test
	void setupBeforeScalingRetainsItsExistingUnscaledContract() {
		ChunkedWork work = rootAndReplay()
				.withChunkSetup(LmdbNativeCostVector.point(Feature.OPEN, 3D), 32)
				.scaled(0.5D, 64);
		assertThat(work.forSlice(1D, 100D).expected(Feature.OPEN)).isEqualTo(3D);
		assertThat(work.forSlice(1D, 100D).expected(Feature.GENERATED_ROW)).isEqualTo(2.5D);
	}

	@Test
	void quotePropertyCopiesKeepBothPhases() {
		LmdbNativeCostQuote quote = quote(rootAndReplay()).ordered(true).distinct(true).withOutputRows(200D);
		assertThat(quote.ordered()).isTrue();
		assertThat(quote.distinct()).isTrue();
		assertThat(quote.forSlice(1D).expected(Feature.BATCH_ROW)).isEqualTo(7D);
		assertThat(quote.forSlice(1D).expected(Feature.GENERATED_ROW)).isEqualTo(5D);
		assertThat(quote.total().expected(Feature.GENERATED_ROW)).isEqualTo(100D);
	}

	@Test
	void explicitBufferedConsumerRaisesOnlyExpectedUpstreamWork() {
		ChunkedWork producer = new ChunkedWork(LmdbNativeCostVector.point(Feature.BATCH_ROW, 16D), 16D, 4);
		ChunkedWork replay = new ChunkedWork(LmdbNativeCostVector.point(Feature.GENERATED_ROW, 16D), 16D, 5);
		LmdbNativeCostQuote original = new LmdbNativeCostQuote(LmdbNativeCostVector.zero(),
				LmdbNativeCostVector.zero(), 16D, false, false, producer.withIndependentPhase(replay));
		LmdbNativeCostQuote buffered = new LmdbNativeCostQuote(LmdbNativeCostVector.zero(),
				LmdbNativeCostVector.zero(), 16D, false, false,
				producer.withBufferedConsumer(16D, 5).withIndependentPhase(replay));
		double[] demands = { 0D, 1D, 5D, 6D, 16D };
		double[] roots = { 0D, 8D, 8D, 12D, 16D };
		double[] entries = { 0D, 5D, 5D, 10D, 16D };
		for (int index = 0; index < demands.length; index++) {
			LmdbNativeCostVector before = original.forSlice(demands[index]);
			LmdbNativeCostVector after = buffered.forSlice(demands[index]);
			assertThat(after.expected(Feature.BATCH_ROW)).isEqualTo(roots[index]);
			assertThat(after.expected(Feature.GENERATED_ROW)).isEqualTo(entries[index]);
			for (Feature feature : Feature.values()) {
				assertThat(after.low(feature)).isEqualTo(before.low(feature));
				assertThat(after.high(feature)).isEqualTo(before.high(feature));
			}
		}
	}

	@Test
	void bufferedConsumerRetainsItsPhysicalPopulationThroughCopiesAndScaling() {
		ChunkedWork work = new ChunkedWork(LmdbNativeCostVector.point(Feature.BATCH_ROW, 16D), 16D, 4)
				.withIndependentPhase(new ChunkedWork(LmdbNativeCostVector.point(Feature.GENERATED_ROW, 16D), 16D, 5))
				.withBufferedConsumer(16D, 5);
		LmdbNativeCostQuote copied = new LmdbNativeCostQuote(LmdbNativeCostVector.zero(), LmdbNativeCostVector.zero(),
				16D, false, false, work).ordered(true).distinct(true).withOutputRows(32D);
		assertThat(copied.forSlice(1D).expected(Feature.BATCH_ROW)).isEqualTo(8D);
		assertThat(copied.forSlice(1D).expected(Feature.GENERATED_ROW)).isEqualTo(5D);
		ChunkedWork scaled = work.scaled(0.5D, 8)
				.withChunkSetup(LmdbNativeCostVector.point(Feature.OPEN, 3D), 4);
		assertThat(scaled.forSlice(1D, 32D).expected(Feature.BATCH_ROW)).isEqualTo(4D);
		assertThat(scaled.forSlice(1D, 32D).expected(Feature.GENERATED_ROW)).isEqualTo(2.5D);
		assertThat(scaled.forSlice(1D, 32D).expected(Feature.OPEN)).isEqualTo(6D);
	}

	@Test
	void expectedFullBufferDoesNotInventAWholeRunLowerBound() {
		ChunkedWork work = new ChunkedWork(LmdbNativeCostVector.point(Feature.BATCH_ROW, 16D), 16D, 4);
		LmdbNativeCostVector original = work.forSlice(9D, 16D);
		LmdbNativeCostVector buffered = work.withBufferedConsumer(16D, 8).forSlice(9D, 16D);
		assertThat(buffered.expected(Feature.BATCH_ROW)).isEqualTo(16D);
		assertThat(buffered.low(Feature.BATCH_ROW)).isEqualTo(original.low(Feature.BATCH_ROW)).isZero();
		assertThat(buffered.high(Feature.BATCH_ROW)).isEqualTo(original.high(Feature.BATCH_ROW));
	}

	@Test
	void unboundedIndependentWorkRemainsUnbounded() {
		ChunkedWork replay = new ChunkedWork(LmdbNativeCostVector.bounds(Feature.GENERATED_ROW, 0D, 100D,
				LmdbNativeCostQuote.UNBOUNDED_COUNT), 100D, 5);
		ChunkedWork work = new ChunkedWork(LmdbNativeCostVector.point(Feature.BATCH_ROW, 7D), 1D, 32)
				.withIndependentPhase(replay);
		assertThat(quote(work).bounded()).isFalse();
		assertThat(quote(work).forSlice(1D).high(Feature.GENERATED_ROW))
				.isEqualTo(LmdbNativeCostQuote.UNBOUNDED_COUNT);
	}

	private static ChunkedWork rootAndReplay() {
		return new ChunkedWork(LmdbNativeCostVector.point(Feature.BATCH_ROW, 7D), 1D, 32)
				.withIndependentPhase(
						new ChunkedWork(LmdbNativeCostVector.point(Feature.GENERATED_ROW, 100D), 100D, 5));
	}

	private static LmdbNativeCostQuote quote(ChunkedWork work) {
		return new LmdbNativeCostQuote(LmdbNativeCostVector.zero(), LmdbNativeCostVector.zero(), 100D,
				false, false, work);
	}
}
